        cx = col - (row - (row & 1))//2
        cz = row
        cy = -cx - cz
        return cx,cy,cz
    cx1,cy1,cz1=to_cube(x1,y1)
    cx2,cy2,cz2=to_cube(x2,y2)
    return (abs(cx1-cx2)+abs(cy1-cy2)+abs(cz1-cz2))//2

